contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt exactly one owner-only call (withdraw) with a bounded amount.
    // We check that if it reverts (because this contract is not owner), depositsCount and c.balance stay the same.
    function run(uint amount) public payable {
        require(amount <= 1 ether);

        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: if the withdraw call reverted, observable state of depositsCount and c.balance is unchanged.
        assert(!reverted || (afterDeposits == beforeDeposits && afterBalance == beforeBalance));
    }

    receive() external payable { }
}

